window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-a7b1b069a4fc96ea"]={"versions": [{"id": "FIG-a7b1b069a4fc96ea", "releases": ["R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Statistisches Schichten- und Blockarchitekturdiagramm der AUTOSAR Classic Platform (Basis-Software-Architektur). Das Diagramm verortet das Modul <code>V2X Management</code> (V2xM) innerhalb der BSW-Schichtenstruktur im Kontext der Schichten Application Layer, AUTOSAR Runtime Environment (RTE), Services Layer, Hardware Abstraction Layer und Microcontroller Abstraction Layer (Drivers).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellte Schichten und Blöcke:</p>\n<ul class=\"fig-list\"><li>Application Layer: Übergeordnete Anwendungsebene oberhalb der RTE.\n</li><li>AUTOSAR Runtime Environment (RTE): Schicht zur Abstraktion und Kommunikation zwischen Applikation und BSW.\n</li><li>Services Layer (blau):\n<ul class=\"fig-list\"><li>System Services: Beinhaltet das Modul <code>NvM</code> (Non-Volatile Memory Manager).\n</li><li>Off-board Communication Services: Beinhaltet den V2X-Protokollstapel mit den Modulen <code>V2X Facilities</code>, <code>V2X Basic TP</code> (V2X Basic Transport Protocol), <code>V2X GeoNetwork</code> und dem vertikal flankierenden Modul <code>V2X Management</code> (rot umrandet als Betrachtungsschwerpunkt).\n</li><li>Crypto Services: Beinhaltet das Modul <code>Crypto Service Manager</code> (CSM).\n</li></ul>\n</li><li>Hardware Abstraction Layer (grün):\n<ul class=\"fig-list\"><li>Wireless Comm. HW Abstraction: Beinhaltet <code>WEthTrcv</code> (Wireless Ethernet Transceiver Driver).\n</li><li>Communication HW Abstraction: Beinhaltet <code>Ethernet Interface</code> (EthIf).\n</li><li>Crypto Hardware Abstraction: Beinhaltet <code>Crypto Interface</code> (CryIf).\n</li></ul>\n</li><li>Drivers Layer (rot/rosa):\n<ul class=\"fig-list\"><li>Wireless Comm. Drivers: Beinhaltet <code>WEth</code> (Wireless Ethernet Driver).\n</li><li>Crypto Drivers: Beinhaltet <code>Crypto Driver</code> (Crypto).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine statische Schichtenarchitektur ohne Sequenzabläufe, Nachrichtenpfade oder dynamische Interaktionsbeziehungen dar. Die vertikale Anordnung indiziert den Schichtenfluss und Kommunikationspfade von der Applikation über RTE, Off-board Communication Services bis zu den Hardware-Treibern.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Modul <code>V2X Management</code> ist durch eine rote Umrandung hervorgehoben und markiert den normativen Gegenstand der Spezifikation. Die Nachbarschaft zu <code>NvM</code>, <code>Crypto Service Manager</code> sowie den V2X-Kommunikationsmodulen und Ethernet-/Wireless-Treibern definiert die primären Architektur- und Schnittstellenbeziehungen für Konfiguration, Schlüsselspeicherung, Diagnose und V2X-Protokollablaufsteuerung.</p>"}, {"id": "FIG-46fc68447276a834", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Statistisches Schichten- und Blockarchitekturdiagramm der AUTOSAR Classic Platform (Basis-Software-Architektur). Das Diagramm verortet das Modul <code>V2X Management</code> (V2xM) innerhalb der BSW-Schichtenstruktur im Kontext der Schichten Application Layer, AUTOSAR Runtime Environment (RTE), Services Layer, Hardware Abstraction Layer und Microcontroller Abstraction Layer (Drivers).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellte Schichten und Blöcke:</p>\n<ul class=\"fig-list\"><li>Application Layer: Übergeordnete Anwendungsebene oberhalb der RTE.\n</li><li>AUTOSAR Runtime Environment (RTE): Schicht zur Abstraktion und Kommunikation zwischen Applikation und BSW.\n</li><li>Services Layer (blau):\n<ul class=\"fig-list\"><li>System Services: Beinhaltet das Modul <code>NvM</code> (Non-Volatile Memory Manager).\n</li><li>Off-board Communication Services: Beinhaltet den V2X-Protokollstapel mit den Modulen <code>V2X Facilities</code>, <code>V2X Basic TP</code> (V2X Basic Transport Protocol), <code>V2X GeoNetwork</code> und dem vertikal flankierenden Modul <code>V2X Management</code> (rot umrandet als Betrachtungsschwerpunkt).\n</li><li>Crypto Services: Beinhaltet das Modul <code>Crypto Service Manager</code> (CSM).\n</li></ul>\n</li><li>Hardware Abstraction Layer (grün):\n<ul class=\"fig-list\"><li>Wireless Comm. HW Abstraction: Beinhaltet <code>WEthTrcv</code> (Wireless Ethernet Transceiver Driver).\n</li><li>Communication HW Abstraction: Beinhaltet <code>Ethernet Interface</code> (EthIf).\n</li><li>Crypto Hardware Abstraction: Beinhaltet <code>Crypto Interface</code> (CryIf).\n</li></ul>\n</li><li>Drivers Layer (rot/rosa):\n<ul class=\"fig-list\"><li>Wireless Comm. Drivers: Beinhaltet <code>WEth</code> (Wireless Ethernet Driver).\n</li><li>Crypto Drivers: Beinhaltet <code>Crypto Driver</code> (Crypto).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine statische Schichtenarchitektur ohne Sequenzabläufe, Nachrichtenpfade oder dynamische Interaktionsbeziehungen dar. Die vertikale Anordnung indiziert den Schichtenfluss und Kommunikationspfade von der Applikation über RTE, Off-board Communication Services bis zu den Hardware-Treibern.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Modul <code>V2X Management</code> ist durch eine rote Umrandung hervorgehoben und markiert den normativen Gegenstand der Spezifikation. Die Nachbarschaft zu <code>NvM</code>, <code>Crypto Service Manager</code> sowie den V2X-Kommunikationsmodulen und Ethernet-/Wireless-Treibern definiert die primären Architektur- und Schnittstellenbeziehungen für Konfiguration, Schlüsselspeicherung, Diagnose und V2X-Protokollablaufsteuerung.</p>"}, {"id": "FIG-81c6cee57d4b032f", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Statistisches Schichten- und Blockarchitekturdiagramm der AUTOSAR Classic Platform zur Einordnung des Moduls <code>V2X Management</code>. Der Fokus liegt auf der internen Struktur der Off-board Communication Services und der direkten Interaktion mit anwendungsspezifischen V2X-Softwarekomponenten über die Runtime Environment (RTE).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellte Schichten und Blöcke:</p>\n<ul class=\"fig-list\"><li>Application Layer: Unterteilt in spezifische Software-Komponenten (<code>POTI</code>, <code>VDP</code>, <code>V2xProxy</code>, <code>SW-C</code>).\n</li><li>Runtime Environment (RTE): Vermittlungsschicht zwischen Application Layer und BSW.\n</li><li>Off-board Communication Services (blau):\n<ul class=\"fig-list\"><li><code>V2X Management</code>: Vertikal gestreckter Block auf der linken Seite.\n</li><li><code>V2X Data Manager</code>: Oberer Block neben <code>V2X Management</code>.\n</li><li><code>V2X Facilities</code>: L-förmig konturierter Block unterhalb von <code>V2X Data Manager</code>.\n</li><li><code>V2X Basic Transport Protocol</code>: Protokollblock unterhalb von <code>V2X Facilities</code>.\n</li><li><code>V2X Geo Networking</code>: Protokollblock unterhalb von <code>V2X Basic Transport Protocol</code>.\n</li></ul>\n</li><li>Communication Hardware Abstraction (grün): Schichtblock unterhalb der Off-board Communication Services (ohne Untermodule).\n</li><li>Communication Drivers (rosa/rot): Treiberschichtblock unterhalb der Hardware-Abstraktion (ohne Untermodule).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm beschreibt eine statische Schichtenarchitektur ohne Kontrollflusspfeile oder Aufrufsequenzen. Die Schichtung zeigt die hierarchische Organisation von den Application-Komponenten über die RTE durch den V2X-Stack bis zu den Hardwareabstraktions- und Treiberschichten.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert den Scope von <code>V2X Management</code> innerhalb des V2X-Stacks. Neben den Protokollschichten (<code>V2X Geo Networking</code>, <code>V2X Basic Transport Protocol</code>, <code>V2X Facilities</code>) existiert ein eigenständiger <code>V2X Data Manager</code>. Über die RTE interagiert der Stack direkt mit dedizierten Applikationskomponenten (<code>POTI</code> für Position and Time Information, <code>VDP</code> für Vehicle Data Provider, <code>V2xProxy</code> und allgemeine <code>SW-C</code>). System- und Krypto-Services werden in diesem Diagramm nicht mehr dargestellt.</p>"}], "trans": [{"from": "FIG-a7b1b069a4fc96ea", "to": "FIG-46fc68447276a834", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-46fc68447276a834", "to": "FIG-81c6cee57d4b032f", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Application Layer: Ergänzung konkreter Software-Komponenten (POTI, VDP, V2xProxy, SW-C).\n</li><li>Runtime Environment (RTE): Entfernung des Präfixes „AUTOSAR“ im Label.\n</li><li>Off-board Communication Services:\n<ul class=\"fig-list\"><li>V2X Management: Vergrößerung und Verschiebung an die linke Flanke der Off-board Communication Services; Wegfall der roten Hervorhebungsumrandung.\n</li><li>V2X Facilities: Formänderung (L-förmige Kontur mit linker Ausbuchtung nach oben).\n</li><li>V2X Data Manager: Neuaufnahme als oberer Block neben V2X Facilities.\n</li><li>V2X Basic TP: Umbenennung in „V2X Basic Transport Protocol“.\n</li><li>V2X GeoNetwork: Umbenennung in „V2X Geo Networking“.\n</li></ul>\n</li><li>System Services: Gesamte Schichtenspalte inklusive Modul NvM entfallen.\n</li><li>Crypto Services: Gesamte Schichtenspalte inklusive Modul Crypto Service Manager entfallen.\n</li><li>Hardware Abstraction Layer:\n<ul class=\"fig-list\"><li>Wireless Comm. HW Abstraction (WEthTrcv) und Crypto Hardware Abstraction (Crypto Interface) sowie Ethernet Interface entfallen.\n</li><li>Schicht vereinheitlicht zu einer durchgehenden Schicht „Communication Hardware Abstraction“ ohne explizite BSW-Untermodule.\n</li></ul>\n</li><li>Driver Layer:\n<ul class=\"fig-list\"><li>Wireless Comm. Drivers (WEth) und Crypto Drivers (Crypto Driver) entfallen.\n</li><li>Schicht vereinheitlicht zu einer durchgehenden Schicht „Communication Drivers“ ohne explizite BSW-Untermodule.\n</li></ul>\n</li></ul>"}]};
